_PLANNER_EVENT_TYPES = {
    "agent.goal.assessed",
    "agent.goal.contract",
    "agent.goal.replan_required",
    "agent.goal.subgoal.opened",
    "agent.intent.selected",
    "agent.plan.created",
    "agent.plan.step",
    "agent.plan.selection",
    "agent.replan.requested",
    "agent.replan.recovery.updated",
    "agent.task_core.created",
    "agent.task.workspace_item.updated",
    "agent.task.todo.updated",
    "agent.task.checkpoint.updated",
}


def _non_planner_timeline_events(timeline: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return [
        event
        for event in timeline
        if event.get("event") not in _PLANNER_EVENT_TYPES
    ]


def _non_planner_run_events(events: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return [
        event
        for event in events
        if event.get("event_type") not in _PLANNER_EVENT_TYPES
    ]


def test_auto_runtime_planner_requests_record_approval_required() -> None:
    timeline: list[dict[str, Any]] = []
    run_events: list[dict[str, Any]] = []

    def run_tool_requests(*_args, **_kwargs) -> None:
        raise AgentApprovalRequired(
            {
                "tool": "desktop.safe_click",
                "approval_id": "approval-click",
                "risk_level": "medium",
                "policy_reason": "desktop_click",
                "input_preview": {"x": 180, "y": 90},
            }
        )

    loop = _private_runtime_loop(
        append_run_event=lambda run_id, event_type, payload: run_events.append(
            {"run_id": run_id, "event_type": event_type, "payload": payload}
        ),
        run_tool_requests=run_tool_requests,
    )
    requests = [
        {
            "tool": "desktop.safe_click",
            "input": {"x": 180, "y": 90},
            "source": "runtime_planner",
            "planning_reason": "planner_replan_ui_observed_action",
            "step_id": "focus-media-search",
            "capability_id": "desktop.ui_operation",
        }
    ]

    with pytest.raises(AgentApprovalRequired):
        loop._run_auto_runtime_planner_requests(
            requests,
            ["desktop.safe_click"],
            {"broker": True},
            [],
            timeline,
            [],
            agent={"name": "Yachiyo"},
            runtime_planner_decision=None,
            run_id="run-approval",
            budget=FakeBudget(),
            next_iteration=0,
        )

    approval_event = next(
        event
        for event in timeline
        if event["event"] == "agent.desktop.intent_approval_required"
    )
    assert approval_event["tool"] == "desktop.safe_click"
    assert approval_event["approval_id"] == "approval-click"
    assert approval_event["risk_level"] == "medium"
    assert approval_event["planning_reason"] == "planner_replan_ui_observed_action"
    _assert_mapping_includes(
        approval_event["input_preview"],
        {
            "x": 180,
            "y": 90,
            "step_id": "focus-media-search",
            "planner_step_id": "focus-media-search",
            "capability_id": "desktop.ui_operation",
        },
    )
    assert any(
        event["event_type"] == "agent.desktop.intent_approval_required"
        and event["payload"]["approval_id"] == "approval-click"
        for event in run_events
    )


def _planner_selection_events(timeline: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return [event for event in timeline if event.get("event") == "agent.plan.selection"]


def _assert_mapping_includes(mapping: dict[str, Any], expected: dict[str, Any]) -> None:
    for key, value in expected.items():
        assert mapping[key] == value


def _assert_planner_task_core_metadata(
    mapping: dict[str, Any],
    *,
    require_task_todo: bool = False,
) -> None:
    assert str(mapping.get("decision_id") or "").startswith("decision-")
    assert str(mapping.get("plan_id") or "").startswith("runtime-plan-")
    assert str(mapping.get("tool_plan_id") or "").startswith("tool-plan-")
    assert str(mapping.get("core_id") or "").startswith("task-core-")
    assert str(mapping.get("workspace_id") or "").startswith("task-workspace-")
    if require_task_todo:
        assert mapping.get("task_todo")


def test_runtime_planner_events_use_workflow_scope_context() -> None:
    decision = RuntimePlanner().decision(
        "请分析 legacy-report.xls 并输出报告",
        allowed_tools=[
            "workspace.read",
            "desktop.open_path",
            "browser.current_page",
            "terminal.run",
            "artifact.write",
        ],
    )
    appended_events: list[dict[str, Any]] = []
    loop = _private_runtime_loop(
        append_run_event=lambda run_id, event_type, payload: appended_events.append(
            {"run_id": run_id, "event_type": event_type, "payload": payload}
        )
    )
    timeline: list[dict[str, Any]] = []
    scope_context = {
        "task_id": "task-workflow-1",
        "workflow_id": "workflow-1",
        "workflow_run_id": "workflow-run-1",
        "workflow_node_id": "node-1",
        "workflow_node_label": "Analyze",
    }

    loop._record_runtime_planner_events(
        decision,
        timeline=timeline,
        run_id="workflow-run-1",
        scope_context=scope_context,
    )

    assert [event["event"] for event in timeline[:4]] == [
        "workflow.run.intent.selected",
        "workflow.run.plan.created",
        "workflow.run.task_core.created",
        "workflow.run.plan.step",
    ]
    intent_event = timeline[0]
    task_core_event = timeline[2]
    todo_event = next(
        event for event in timeline if event["event"] == "workflow.run.task.todo.updated"
    )
    assert intent_event["workflow_run_id"] == "workflow-run-1"
    assert intent_event["payload"]["planner_event_type"] == "agent.intent.selected"
    assert intent_event["payload"]["planner_scope"] == "workflow.run"
    assert task_core_event["payload"]["planner_event_type"] == "agent.task_core.created"
    assert task_core_event["payload"]["workflow_node_id"] == "node-1"
    assert todo_event["planner_event_type"] == "agent.task.todo.updated"
    assert todo_event["planner_scope"] == "workflow.run"
    assert todo_event["task_id"] == "task-workflow-1"
    assert [event["event_type"] for event in appended_events[:4]] == [
        "workflow.run.intent.selected",
        "workflow.run.plan.created",
        "workflow.run.task_core.created",
        "workflow.run.plan.step",
    ]
    assert appended_events[0]["payload"]["planner_event_type"] == "agent.intent.selected"


def test_runtime_planner_event_dedupe_isolated_by_progress_scope() -> None:
    decision = RuntimePlanner().decision(
        "请分析 legacy-report.xls 并输出报告",
        allowed_tools=[
            "workspace.read",
            "desktop.open_path",
            "browser.current_page",
            "terminal.run",
            "artifact.write",
        ],
    )
    appended_events: list[dict[str, Any]] = []
    loop = _private_runtime_loop(
        append_run_event=lambda run_id, event_type, payload: appended_events.append(
            {"run_id": run_id, "event_type": event_type, "payload": payload}
        )
    )
    timeline: list[dict[str, Any]] = []

    loop._record_runtime_planner_events(
        decision,
        timeline=timeline,
        run_id="group-run-1",
        scope_context={"task_id": "task-group-1", "group_run_id": "group-run-1"},
    )
    loop._record_runtime_planner_events(
        decision,
        timeline=timeline,
        run_id="workflow-run-1",
        scope_context={
            "task_id": "task-workflow-1",
            "workflow_run_id": "workflow-run-1",
            "workflow_node_id": "node-1",
        },
    )

    group_todos = [
        event
        for event in timeline
        if event["event"] == "group.run.task.todo.updated"
    ]
    workflow_todos = [
        event
        for event in timeline
        if event["event"] == "workflow.run.task.todo.updated"
    ]
    assert len(group_todos) == len(decision.plan.task_core.todos)
    assert len(workflow_todos) == len(decision.plan.task_core.todos)
    assert {event["task_id"] for event in group_todos} == {"task-group-1"}
    assert {event["task_id"] for event in workflow_todos} == {"task-workflow-1"}
    assert any(
        event["run_id"] == "group-run-1"
        and event["event_type"] == "group.run.task.todo.updated"
        for event in appended_events
    )
    assert any(
        event["run_id"] == "workflow-run-1"
        and event["event_type"] == "workflow.run.task.todo.updated"
        for event in appended_events
    )


