def test_runtime_loop_auto_executes_deferred_ui_action_after_observation() -> None:
    budget = FakeBudget()
    timeline: list[dict[str, Any]] = []
    executed_tools: list[str] = []

    def run_tool_requests(
        tool_requests,
        _allowed_tools,
        _broker,
        _messages_arg,
        timeline_arg,
        _artifacts,
        **_kwargs,
    ):
        for request in tool_requests:
            tool_name = request["tool"]
            executed_tools.append(tool_name)
            if tool_name == "desktop.list_apps":
                result = {
                    "ok": True,
                    "data": {
                        "apps": [{"name": "PixelForge", "path": "/Applications/PixelForge.app"}]
                    },
                }
            elif tool_name == "app.open":
                result = {"ok": True, "data": {"app_name": "PixelForge"}}
            elif tool_name == "desktop.ui_elements":
                result = {
                    "ok": True,
                    "data": {
                        "app_name": "PixelForge",
                        "postcondition_verified": True,
                        "elements": [
                            {"role": "button", "label": "登录"},
                        ],
                    },
                }
            elif tool_name == "app.open_and_click_ui_element":
                result = {"ok": True, "data": {"matched_label": "登录"}}
            else:
                result = {"ok": True}
            _append_fake_runtime_tool_call(
                timeline_arg,
                request,
                result,
                run_id=str(_kwargs.get("run_id") or ""),
            )

    loop = RuntimeCustomApiAgentLoop(
        agent_model_config_private=lambda _agent: {
            "base_url": "https://model.local",
            "model": "m",
            "api_key": "k",
        },
        compile_agent_runtime=lambda _agent: {
            "tool_policy": {
                "allowed_tools": [
                    "desktop.list_apps",
                    "app.open",
                    "desktop.ui_elements",
                    "app.open_and_click_ui_element",
                ]
            }
        },
        run_budget=lambda _run_id, _timeline_value: budget,
        check_context_budget=lambda _budget, _messages: None,
        tool_schemas=lambda allowed_tools: [{"name": tool} for tool in allowed_tools],
        normalize_tool_iteration=lambda value: int(value or 0),
        max_tool_iterations=3,
        operating_doctrine="",
        memory_tool_names=set(),
        future_task_tool_names=set(),
        call_model=lambda *_args, **_kwargs: (_ for _ in ()).throw(
            AssertionError("deferred observed UI followup should not call model")
        ),
        coalesce_model_message=lambda value: value,
        message_visible_content_text=lambda message: str(message.get("content") or ""),
        model_message_metadata=lambda _message: {},
        tool_requests_from_message=lambda _message, _content: [],
        timeline_factory=_timeline,
        limit_model_output=lambda value: (str(value), False),
        model_output_text_factory=agent_runtime._ModelOutputText,
        tool_loop_projection=FakeToolLoopProjection(),
        run_tool_requests=run_tool_requests,
        error_type=agent_runtime.AgentRuntimeError,
    )

    with pytest.raises(
        AgentDirectOutcomeUnverified,
        match="未能确认界面已按预期变化",
    ) as unverified:
        loop.run(
            {"name": "Yachiyo"},
            "打开 PixelForge 点击登录",
            broker=object(),
            timeline=timeline,
            artifacts=[],
            run_id="run-deferred-ui",
        )

    assert executed_tools == [
        "desktop.list_apps",
        "app.open",
        "desktop.ui_elements",
        "app.open_and_click_ui_element",
        "desktop.ui_elements",
    ]
    assert unverified.value.reason == "desktop_verification_missing"
    assert unverified.value.tool_name == "app.open_and_click_ui_element"
    planned = [
        event
        for event in timeline
        if event.get("event") == "agent.desktop.intent_planned"
        and event.get("tool") == "app.open_and_click_ui_element"
    ]
    assert planned
    assert planned[-1]["action_target"] == {
        "kind": "desktop_app",
        "action": "click_ui",
        "app_name": "PixelForge",
        "target": "登录",
        "role_filter": "button",
        "limit": 80,
        "click_count": 1,
        "selection_source": "direct_app_name",
        "query": "PixelForge",
    }


