def test_auto_replan_runtime_recovery_actions_respect_manual_auto_start_metadata() -> None:
    requests = custom_api_agent_module._auto_replan_runtime_recovery_action_requests(
        [
            {
                "request_id": "replan-safe",
                "trigger": "tool_failure",
                "metadata": {
                    "recovery_actions": [
                        {
                            "label": "Discover app again",
                            "tool": "desktop.list_apps",
                            "input": {"query": "PixelForge", "limit": 20},
                            "risk_level": "low",
                            "metadata": {
                                "runtime_replan_auto_start_eligible": True,
                                "runtime_replan_auto_start_blockers": [],
                            },
                        },
                        {
                            "label": "Bring PixelForge forward",
                            "tool": "app.open",
                            "input": {"app_name": "PixelForge"},
                            "risk_level": "low",
                            "metadata": {
                                "runtime_replan_auto_start_eligible": True,
                                "runtime_replan_auto_start_blockers": [],
                            },
                            "deferred_continuation": [
                                {
                                    "tool": "desktop.active_window",
                                    "input": {},
                                    "verification_target": {"app_name": "PixelForge"},
                                }
                            ],
                        },
                        {
                            "label": "Run fallback script",
                            "tool": "terminal.run",
                            "input": {"command": "python analyze_sales.py"},
                            "risk_level": "high",
                            "metadata": {
                                "runtime_replan_auto_start_eligible": False,
                                "runtime_replan_auto_start_blockers": [
                                    "high_risk",
                                    "tool_not_auto_safe",
                                ],
                            },
                        },
                        {
                            "label": "Raw script action without metadata",
                            "tool": "terminal.run",
                            "input": {"command": "python raw_recovery.py"},
                            "risk_level": "low",
                        },
                        {
                            "label": "Open Chrome for external CDP recovery",
                            "tool": "app.open",
                            "input": {"app_name": "Google Chrome"},
                            "risk_level": "low",
                            "permission_target": "chrome_cdp",
                            "metadata": {
                                "runtime_replan_auto_start_eligible": True,
                                "runtime_replan_auto_start_blockers": [],
                            },
                        },
                    ]
                },
            }
        ],
        ["desktop.list_apps", "app.open", "desktop.active_window", "terminal.run"],
    )

    assert [request["tool"] for request in requests] == ["desktop.list_apps", "app.open"]
    assert requests[0]["input"] == {"query": "PixelForge", "limit": 20}
    assert requests[0]["replan_request_id"] == "replan-safe"
    assert requests[1]["input"] == {"app_name": "PixelForge"}
    assert "continue_to_model" not in requests[1]
    deferred = requests[1]["deferred_continuation"]
    assert deferred[0]["replan_recovery_identity"].startswith("replan-recovery-")
    assert [
        {key: value for key, value in request.items() if key != "replan_recovery_identity"}
        for request in deferred
    ] == [
        {
            "tool": "desktop.active_window",
            "input": {},
            "verification_target": {"app_name": "PixelForge"},
            "replan_request_id": "replan-safe",
            "replan_trigger": "tool_failure",
            "replan_triggers": ["tool_failure"],
            "source": "runtime_planner",
            "planning_reason": "planner_replan_deferred_continuation",
        }
    ]


