@pytest.mark.parametrize("open_tool", ["app.open", "desktop.open_app"])
@pytest.mark.parametrize(
    "deferred_fields",
    [
        {
            "deferred_continuation": [
                {"tool": "desktop.active_window", "input": {}}
            ]
        },
        {
            "deferred_tool": "desktop.active_window",
            "deferred_input": {},
        },
    ],
)
def test_pending_replan_resume_keeps_completed_open_and_runs_deferred_observation(
    open_tool: str,
    deferred_fields: dict[str, Any],
) -> None:
    run_id = f"run-pending-replan-{open_tool.replace('.', '-')}"
    executed_requests: list[dict[str, Any]] = []
    timeline: list[dict[str, Any]] = []

    def run_tool_requests(
        requests: list[dict[str, Any]],
        *_args: Any,
        **_kwargs: Any,
    ) -> None:
        executed_requests.extend(dict(request) for request in requests)
        for request in requests:
            _append_fake_runtime_tool_call(
                timeline,
                request,
                {"ok": True, "status": "ok"},
                run_id=run_id,
            )

    replan_payload = {
        "request_id": "replan-resume-open-observe",
        "trigger": "tool_failure",
        "source": "runtime_tool_request_runner",
        "source_step_id": "recover-desktop-action",
        "source_tool_name": "desktop.verify",
        "runtime_tool_timeline_start": 0,
        "metadata": {
            "recovery_actions": [
                {
                    "tool": open_tool,
                    "input": {"app_name": "PixelForge"},
                    "risk_level": "low",
                    "metadata": {
                        "runtime_replan_auto_start_eligible": True,
                        "runtime_replan_auto_start_blockers": [],
                    },
                    **deferred_fields,
                }
            ]
        },
    }
    contract, live_payloads = _production_pending_replan_goal_fixture(
        timeline,
        [
            (
                replan_payload,
                "criterion-resume-observation",
                "desktop.app_discovery",
                {
                    "kind": "desktop_discovery",
                    "action": "verify_after_action",
                    "app_name": "PixelForge",
                },
            )
        ],
        run_id=run_id,
    )
    replan_payload = live_payloads[0]
    _append_fake_runtime_tool_call(
        timeline,
        {
            "tool": open_tool,
            "input": {"app_name": "PixelForge"},
            "plan_id": "plan-completed-open",
            "step_id": "completed-open",
            "request_id": "request-completed-open",
            "tool_call_id": "call-completed-open",
        },
        {"ok": True, "status": "ok"},
        run_id=run_id,
    )
    timeline.append(
        _timeline(
            "agent.replan.requested",
            "tool_failure",
            source="runtime_tool_request_runner",
            payload=replan_payload,
        )
    )
    loop = _private_runtime_loop(run_tool_requests=run_tool_requests)

    loop._run_pending_runtime_replan_recovery(
        [open_tool, "desktop.active_window"],
        RecordingDesktopBroker([]),
        [{"role": "user", "content": "Resume the pending desktop task"}],
        timeline,
        [],
        agent={"name": "Yachiyo"},
        run_id=run_id,
        budget=FakeBudget(),
        next_iteration=1,
        goal_contract=contract,
    )

    assert [request["tool"] for request in executed_requests] == [
        "desktop.active_window"
    ]
    assert executed_requests[0]["replan_request_id"] == (
        "replan-resume-open-observe"
    )


@pytest.mark.parametrize("legacy_start", [None, 0])
def test_pending_replan_resume_scopes_idempotency_per_payload(
    legacy_start: int | None,
) -> None:
    run_id = "run-pending-replan-scoped"
    executed_requests: list[dict[str, Any]] = []
    timeline: list[dict[str, Any]] = []

    def run_tool_requests(
        requests: list[dict[str, Any]],
        *_args: Any,
        **_kwargs: Any,
    ) -> None:
        executed_requests.extend(dict(request) for request in requests)
        for request in requests:
            _append_fake_runtime_tool_call(
                timeline,
                request,
                {"ok": True, "status": "ok"},
                run_id=run_id,
            )

    legacy_payload = {
        "request_id": "replan-legacy-open-observe",
        "trigger": "tool_failure",
        "source": "runtime_tool_request_runner",
        "source_step_id": "legacy-recovery",
        "source_tool_name": "desktop.verify",
        "metadata": {
            "recovery_actions": [
                {
                    "tool": "app.open",
                    "input": {"app_name": "PixelForge"},
                    "risk_level": "low",
                    "metadata": {"runtime_replan_auto_start_eligible": True},
                    "deferred_tool": "desktop.active_window",
                    "deferred_input": {},
                }
            ]
        },
    }
    if legacy_start is not None:
        legacy_payload["runtime_tool_timeline_start"] = legacy_start
    current_payload = {
        "request_id": "replan-current-reopen",
        "trigger": "tool_failure",
        "source": "runtime_tool_request_runner",
        "source_step_id": "current-recovery",
        "source_tool_name": "app.open",
        "metadata": {
            "recovery_actions": [
                {
                    "tool": "app.open",
                    "input": {"app_name": "PixelForge"},
                    "risk_level": "low",
                    "continue_to_model": False,
                    "metadata": {"runtime_replan_auto_start_eligible": True},
                }
            ]
        },
    }
    contract, live_payloads = _production_pending_replan_goal_fixture(
        timeline,
        [
            (
                legacy_payload,
                "criterion-legacy-observation",
                "desktop.app_discovery",
                {
                    "kind": "desktop_discovery",
                    "action": "verify_after_action",
                    "app_name": "PixelForge",
                },
            ),
            (
                current_payload,
                "criterion-current-open",
                "desktop.app_control",
                {
                    "kind": "desktop_app",
                    "action": "open_app",
                    "app_name": "PixelForge",
                },
            ),
        ],
        run_id=run_id,
    )
    legacy_payload, current_payload = live_payloads
    current_source = timeline.pop()
    _append_fake_runtime_tool_call(
        timeline,
        {
            "tool": "app.open",
            "input": {"app_name": "PixelForge"},
            "plan_id": "plan-completed-open",
            "step_id": "completed-open",
            "request_id": "request-completed-open",
            "tool_call_id": "call-completed-open",
        },
        {"ok": True, "status": "ok"},
        run_id=run_id,
    )
    timeline.append(current_source)
    current_payload["runtime_tool_timeline_start"] = len(timeline) - 1
    timeline.extend(
        [
            _timeline(
                "agent.replan.requested",
                "legacy failure",
                source="runtime_tool_request_runner",
                payload=legacy_payload,
            ),
            _timeline("agent.model.followup", "batch boundary"),
            _timeline(
                "agent.replan.requested",
                "current failure",
                source="runtime_tool_request_runner",
                payload=current_payload,
            ),
        ]
    )
    loop = _private_runtime_loop(run_tool_requests=run_tool_requests)

    with pytest.raises(
        AgentDirectOutcomeUnverified,
        match="未能确认界面已按预期变化",
    ) as unverified:
        loop._run_pending_runtime_replan_recovery(
            ["app.open", "desktop.active_window"],
            RecordingDesktopBroker([]),
            [{"role": "user", "content": "Resume pending desktop work"}],
            timeline,
            [],
            agent={"name": "Yachiyo"},
            run_id=run_id,
            budget=FakeBudget(),
            next_iteration=1,
            goal_contract=contract,
        )

    assert unverified.value.reason == "desktop_verification_missing"
    assert [request["tool"] for request in executed_requests] == [
        "desktop.active_window",
        "app.open",
    ]
    assert executed_requests[-1]["replan_request_id"] == "replan-current-reopen"


def test_auto_replan_verification_recovery_inspects_target_app_when_available() -> None:
    recovery_requests = custom_api_agent_module._auto_replan_verification_recovery_requests(
        [
            {
                "request_id": "replan-inspect",
                "trigger": "verification_failed",
                "decision_id": "decision-inspect",
                "plan_id": "plan-inspect",
                "source_step_id": "verify-desktop-result",
                "source_tool_name": "desktop.ui_elements",
                "target_capability_id": "desktop.app_discovery",
                "failure_detail": "verification observation returned no UI elements or readable text",
                "verification_targets": [
                    {
                        "step_id": "search-logo-template",
                        "todo_id": "todo-search-logo-template",
                    }
                ],
                "action_target": {
                    "action": "verify_after_action",
                    "step_id": "search-logo-template",
                    "app_name": "Figma",
                },
                "observation_evidence": {
                    "source_tool": "desktop.ui_elements",
                    "verification_failed": True,
                },
                "observation_retry": {
                    "tool": "desktop.ui_elements",
                    "input": {"app_name": "Figma", "limit": 80},
                },
                "metadata": {
                    "runtime_stage": "verify",
                    "runtime_role": "verify_result",
                    "target_app_name": "Figma",
                    "target_search_text": "logo 模板",
                },
            }
        ],
        [
            "desktop.active_window",
            "desktop.inspect_app",
            "desktop.list_windows",
            "desktop.ui_elements",
            "screen.capture",
        ],
    )

    assert [request["tool"] for request in recovery_requests] == [
        "desktop.active_window",
        "desktop.inspect_app",
        "desktop.list_windows",
        "desktop.ui_elements",
        "screen.capture",
    ]
    assert recovery_requests[1]["input"] == {
        "app_name": "Figma",
        "open_if_needed": True,
        "focus": True,
        "limit": 80,
    }
    assert recovery_requests[0]["verification_target"] == {"app_name": "Figma"}
    assert all(request["continue_to_model"] is True for request in recovery_requests)
    assert {request["target_app_name"] for request in recovery_requests} == {"Figma"}
    assert {request["replan_request_id"] for request in recovery_requests} == {
        "replan-inspect"
    }
    assert {request["decision_id"] for request in recovery_requests} == {
        "decision-inspect"
    }
    assert {request["plan_id"] for request in recovery_requests} == {"plan-inspect"}
    assert {request["action_target"]["step_id"] for request in recovery_requests} == {
        "search-logo-template"
    }
    assert {
        request["observation_evidence"]["source_tool"] for request in recovery_requests
    } == {"desktop.ui_elements"}
    assert {request["observation_retry"]["tool"] for request in recovery_requests} == {
        "desktop.ui_elements"
    }
    assert {
        request["verification_targets"][0]["todo_id"] for request in recovery_requests
    } == {"todo-search-logo-template"}


