def test_custom_api_agent_loop_refocuses_after_active_window_mismatch_without_model() -> None:
    allowed_tools = [
        "desktop.list_apps",
        "app.open",
        "desktop.active_window",
        "app.focus",
    ]
    budget = FakeBudget()
    tool_batches: list[list[dict[str, Any]]] = []
    active_window_calls = 0
    run_id = "run-focus-recovery-direct"
    goal = "打开 PixelForge 并告诉我当前前台窗口"
    contract = _effectful_test_goal_contract(
        run_id=run_id,
        original_goal=goal,
        capability_id="desktop.app_control",
        source_step_id="open-or-focus-app",
        verifier_step_ids=("verify-desktop-result",),
        expected_state="open",
        expected_target={
            "kind": "desktop_app",
            "action": "open_app",
            "app_name": "PixelForge",
        },
    )

    def run_tool_requests(
        tool_requests,
        _allowed_tools,
        _broker,
        messages_arg,
        timeline_arg,
        _artifacts,
        **_kwargs,
    ):
        nonlocal active_window_calls
        tool_batches.append([dict(request) for request in tool_requests])
        for request in tool_requests:
            tool = str(request.get("tool") or "")
            payload = request.get("input") if isinstance(request.get("input"), dict) else {}
            if tool == "desktop.list_apps":
                result = {"ok": True, "data": {"apps": [{"name": "PixelForge"}]}}
            elif tool == "app.open":
                result = {"ok": True, "data": {"app_name": "PixelForge"}}
            elif tool == "app.focus":
                result = {
                    "ok": True,
                    "data": {
                        "app_name": payload.get("app_name"),
                        "focus_verified": True,
                    },
                }
            elif tool == "desktop.active_window":
                active_window_calls += 1
                if active_window_calls == 1:
                    result = {
                        "ok": False,
                        "error": "foreground_focus_unverified",
                        "verification_failed": True,
                        "blocking_condition": "foreground_focus_unverified",
                        "data": {
                            "expected_app_name": "PixelForge",
                            "active_app_name": "Finder",
                            "focus_verified": False,
                        },
                    }
                else:
                    result = {
                        "ok": True,
                        "postcondition_verified": True,
                        "data": {
                            "app_name": "PixelForge",
                            "expected_app_name": "PixelForge",
                            "active_app_name": "PixelForge",
                            "focus_verified": True,
                            "postcondition_verified": True,
                        },
                    }
            else:
                raise AssertionError(f"unexpected tool: {tool}")
            _append_fake_runtime_tool_call(
                timeline_arg,
                request,
                result,
                run_id=str(_kwargs.get("run_id") or ""),
            )
            messages_arg.append({"role": "user", "content": f"Tool result for {tool}: {result}"})

    loop = RuntimeCustomApiAgentLoop(
        agent_model_config_private=lambda _agent: {
            "base_url": "https://model.local",
            "model": "m",
            "api_key": "k",
        },
        compile_agent_runtime=lambda _agent: {"tool_policy": {"allowed_tools": allowed_tools}},
        run_budget=lambda _run_id, _timeline_value: budget,
        check_context_budget=lambda _budget, _messages: None,
        tool_schemas=lambda tools: [{"name": tool} for tool in tools],
        normalize_tool_iteration=lambda value: int(value or 0),
        max_tool_iterations=3,
        operating_doctrine="Use runtime planner for desktop actions.",
        memory_tool_names=set(),
        future_task_tool_names=set(),
        call_model=lambda *_args, **_kwargs: (_ for _ in ()).throw(
            AssertionError("model should not be called for focus recovery")
        ),
        coalesce_model_message=lambda value: value,
        message_visible_content_text=lambda message: str(message.get("content") or ""),
        model_message_metadata=lambda _message: {},
        tool_requests_from_message=lambda *_args, **_kwargs: [],
        timeline_factory=_timeline,
        limit_model_output=lambda value: (str(value), False),
        model_output_text_factory=agent_runtime._ModelOutputText,
        tool_loop_projection=FakeToolLoopProjection(),
        run_tool_requests=run_tool_requests,
        error_type=agent_runtime.AgentRuntimeError,
    )
    timeline: list[dict[str, Any]] = []

    with pytest.raises(AgentDirectOutcomeUnverified) as exc_info:
        loop.run(
            {"name": "Yachiyo"},
            goal,
            broker={"broker": True},
            timeline=timeline,
            artifacts=[],
            run_id=run_id,
            runtime_execution_metadata={"goal_contract": contract.to_payload()},
        )

    assert [[request["tool"] for request in batch] for batch in tool_batches] == [
        ["desktop.list_apps", "app.open", "desktop.active_window"],
    ]
    assert budget.claims == 0
    assert exc_info.value.reason == "desktop_verification_missing"
    assert exc_info.value.tool_name == "app.open"
    assert exc_info.value.input_preview["app_name"] == "PixelForge"
    assert not any(event["event"] == "agent.model.followup_context" for event in timeline)
    recovery_plan_events = [
        event
        for event in timeline
        if event["event"] == "agent.desktop.intent_planned"
        and event.get("planning_reason") == "planner_replan_focus_recovery"
    ]
    assert recovery_plan_events == []
    assert not any(
        event.get("event") == "agent.desktop.intent_completed"
        for event in timeline
    )


def test_model_replan_followup_context_includes_task_core_workspace() -> None:
    task_core = {
        "core_id": "core-data",
        "workspace": {
            "workspace_id": "workspace-data",
            "title": "Data Analysis Workspace",
            "items": [
                {
                    "item_id": "input-sales",
                    "kind": "input",
                    "path": "sales.csv",
                    "status": "available",
                },
                {
                    "item_id": "code-area-studio",
                    "kind": "input",
                    "path": "apps/frontend/src/features/agent-studio",
                    "status": "planned",
                    "source_step_id": "inspect-code-area-1",
                    "metadata": {
                        "role": "code_area_context",
                        "pattern": "*Timeline*",
                    },
                }
            ],
        },
        "todos": [
            {
                "todo_id": "todo-analyze",
                "step_id": "analyze-data-file",
                "title": "Analyze data file",
                "tool_name": "data.analyze",
                "status": "planned",
            }
        ],
        "checkpoints": [
            {
                "checkpoint_id": "checkpoint-analyze",
                "after_step_id": "analyze-data-file",
                "title": "Verify analysis output",
                "status": "planned",
            }
        ],
        "replan_signals": [],
    }
    payload = custom_api_agent_module._model_replan_followup_context_payload(
        [
            {
                "request_id": "replan-data",
                "trigger": "tool_failure",
                "decision_id": "decision-data",
                "plan_id": "plan-data",
                "core_id": "core-data",
                "source_step_id": "analyze-data-file",
                "source_tool_name": "data.analyze",
                "target_capability_id": "data.analysis",
                "fallback_tools": ["terminal.run"],
                "failure_detail": "data.analyze returned unsupported format",
            }
        ],
        allowed_tools=["terminal.run"],
        timeline=[
            _timeline(
                "agent.task_core.created",
                "Data Analysis Workspace",
                core_id="core-data",
                plan_id="plan-data",
                payload={
                    "core_id": "core-data",
                    "plan_id": "plan-data",
                    "task_core": task_core,
                },
            ),
            _timeline(
                "agent.task.todo.updated",
                "Analyze data file",
                core_id="core-data",
                plan_id="plan-data",
                step_id="analyze-data-file",
                status="blocked",
                todo={
                    "step_id": "analyze-data-file",
                    "title": "Analyze data file",
                    "tool_name": "data.analyze",
                },
            ),
        ],
    )
    message = custom_api_agent_module._model_replan_followup_context_message(payload)

    assert payload["task_core"]["core_id"] == task_core["core_id"]
    assert payload["task_core"]["todos"][0]["status"] == "blocked"
    assert payload["task_core"]["checkpoints"][0]["status"] == "blocked"
    assert payload["task_progress"]["blocked_steps"] == ["analyze-data-file"]
    assert "Task workspace:" in message
    assert "- workspace: Data Analysis Workspace" in message
    assert "input · available · sales.csv" in message
    assert (
        "input · planned · apps/frontend/src/features/agent-studio · "
        "inspect-code-area-1 · *Timeline*"
    ) in message
    assert "analyze-data-file · blocked · data.analyze" in message
    assert "analyze-data-file · blocked · Verify analysis output" in message


def test_custom_api_agent_loop_continues_after_verification_recovery_observation() -> None:
    allowed_tools = [
        "desktop.list_apps",
        "app.open",
        "desktop.safe_shortcut",
        "desktop.safe_type_text",
        "desktop.search_submit",
        "desktop.ui_elements",
        "desktop.active_window",
        "desktop.list_windows",
        "screen.capture",
    ]
    model_calls: list[list[dict[str, Any]]] = []
    tool_runs: list[list[str]] = []

    def run_tool_requests(
        tool_requests,
        _allowed_tools,
        _broker,
        messages_arg,
        timeline_arg,
        _artifacts,
        **_kwargs,
    ):
        tool_runs.append([str(request.get("tool") or "") for request in tool_requests])
        for request in tool_requests:
            tool = str(request.get("tool") or "")
            payload = request.get("input") if isinstance(request.get("input"), dict) else {}
            if tool == "desktop.list_apps":
                result = {"ok": True, "data": {"apps": [{"name": "Figma"}]}}
            elif tool == "app.open":
                result = {"ok": True, "data": {"app_name": payload.get("app_name")}}
            elif tool in {"desktop.safe_shortcut", "desktop.safe_type_text", "desktop.search_submit"}:
                result = {"ok": True}
            elif tool == "desktop.ui_elements":
                result = {"ok": True, "data": {"elements": [], "count": 0, "text_item_count": 0}}
            elif tool == "desktop.active_window":
                result = {"ok": True, "data": {"app_name": "Figma", "title": "Logo templates"}}
            elif tool == "desktop.list_windows":
                result = {
                    "ok": True,
                    "data": {"windows": [{"app_name": "Figma", "title": "Logo templates"}]},
                }
            elif tool == "screen.capture":
                result = {"ok": True, "summary": "已截取验证画面。", "data": {"path": "verify.png"}}
            else:
                raise AssertionError(f"unexpected tool: {tool}")
            _append_fake_runtime_tool_call(
                timeline_arg,
                request,
                result,
                run_id=str(_kwargs.get("run_id") or ""),
            )
            messages_arg.append({"role": "user", "content": f"Tool result for {tool}: {result}"})

    loop = RuntimeCustomApiAgentLoop(
        agent_model_config_private=lambda _agent: {
            "base_url": "https://model.local",
            "model": "m",
            "api_key": "k",
        },
        compile_agent_runtime=lambda _agent: {"tool_policy": {"allowed_tools": allowed_tools}},
        run_budget=lambda _run_id, _timeline_value: FakeBudget(),
        check_context_budget=lambda _budget, _messages: None,
        tool_schemas=lambda tools: [{"name": tool} for tool in tools],
        normalize_tool_iteration=lambda value: int(value or 0),
        max_tool_iterations=3,
        operating_doctrine="Use runtime planner for desktop actions.",
        memory_tool_names=set(),
        future_task_tool_names=set(),
        call_model=lambda _base_url, _model, _api_key, model_messages, **_kwargs: model_calls.append(
            list(model_messages)
        )
        or {"role": "assistant", "content": "model fallback"},
        coalesce_model_message=lambda value: value,
        message_visible_content_text=lambda message: str(message.get("content") or ""),
        model_message_metadata=lambda _message: {},
        tool_requests_from_message=lambda *_args, **_kwargs: [],
        timeline_factory=_timeline,
        limit_model_output=lambda value: (str(value), False),
        model_output_text_factory=agent_runtime._ModelOutputText,
        tool_loop_projection=FakeToolLoopProjection(),
        run_tool_requests=run_tool_requests,
        error_type=agent_runtime.AgentRuntimeError,
    )
    timeline: list[dict[str, Any]] = []

    with pytest.raises(agent_runtime.AgentRuntimeError) as failure:
        loop.run(
            {"name": "Yachiyo"},
            "帮我打开一个设计工具，搜索 logo 模板",
            broker={"broker": True},
            timeline=timeline,
            artifacts=[],
            run_id="run-verify-recovery-direct",
        )

    assert str(failure.value) == "custom_api Agent 工具循环超过上限；loop detail"
    assert tool_runs == [
        [
            "desktop.list_apps",
            "app.open",
            "desktop.safe_shortcut",
            "desktop.safe_type_text",
            "desktop.search_submit",
            "desktop.ui_elements",
        ]
    ]
    assert len(model_calls) == 3
    assert sum(
        event.get("event") == "agent.goal.replan_required"
        for event in timeline
    ) == 3
    assert not any(
        event.get("event") == "agent.replan.requested"
        and event.get("payload", {}).get("trigger") == "planner_authority_conflict"
        for event in timeline
    )
    assert not any(
        event.get("event") == "agent.desktop.intent_completed"
        for event in timeline
    )


