def test_auto_followup_dispatches_observed_desktop_click_action() -> None:
    selection_payload = {
        "followup_target": {
            "kind": "desktop_observed_action",
            "target_action": "click",
            "target": "登录",
            "role_filter": "button",
            "click_count": 1,
            "limit": 80,
        }
    }
    timeline = [
        _timeline(
            "agent.tool.call",
            "desktop.read_ui",
            input_preview={"role_filter": "button", "limit": 80},
            result={
                "ok": True,
                "data": {"elements": [{"label": "登录", "center": {"x": 120, "y": 240}}]},
            },
        )
    ]

    semantic_click = custom_api_agent_module._auto_discovered_followup_requests(
        selection_payload,
        ["desktop.read_ui", "desktop.click_ui_element"],
        timeline,
    )
    assert [
        {
            "tool": request["tool"],
            "input": request["input"],
            "planning_reason": request["planning_reason"],
        }
        for request in semantic_click
    ] == [
        {
            "tool": "desktop.click_ui_element",
            "input": {
                "target": "登录",
                "role_filter": "button",
                "click_count": 1,
                "limit": 80,
            },
            "planning_reason": "planner_followup_desktop_observed_action",
        },
        {
            "tool": "desktop.read_ui",
            "input": {"role_filter": "button", "limit": 80},
            "planning_reason": "planner_followup_desktop_observed_action",
        }
    ]
    assert semantic_click[0]["capability_id"] == "desktop.ui_operation"
    assert semantic_click[0]["action_target"] == {
        "kind": "desktop_observed_action",
        "action": "click",
        "target": "登录",
        "role_filter": "button",
    }
    assert semantic_click[0]["observation_evidence"] == {
        "source_tool": "desktop.read_ui",
        "strategy": "semantic_ui_tool",
    }
    assert semantic_click[1]["action_target"] == {
        "kind": "desktop_observed_action",
        "action": "verify_after_action",
        "target": "登录",
        "role_filter": "button",
    }
    assert semantic_click[1]["observation_evidence"] == {
        "source_tool": "desktop.read_ui",
        "strategy": "post_action_observation",
    }

    app_scoped_click = custom_api_agent_module._auto_discovered_followup_requests(
        {
            "followup_target": {
                **selection_payload["followup_target"],
                "app_name": "Figma",
                "app_query": "image",
            }
        },
        [
            "desktop.read_ui",
            "app.focus_and_click_ui_element",
            "desktop.click_ui_element",
        ],
        timeline,
    )
    assert [request["tool"] for request in app_scoped_click] == [
        "app.focus_and_click_ui_element",
        "desktop.read_ui",
    ]
    assert app_scoped_click[0]["input"] == {
        "app_name": "Figma",
        "target": "登录",
        "role_filter": "button",
        "click_count": 1,
        "limit": 80,
    }
    assert app_scoped_click[0]["input_resolution"] == {
        "tool": "app.focus_and_click_ui_element",
        "field": "app_name",
        "requested_app_name": "image",
        "resolved_app_name": "Figma",
        "source_tool": "desktop.list_apps",
    }
    assert app_scoped_click[0]["action_target"] == {
        "kind": "desktop_observed_action",
        "action": "click",
        "target": "登录",
        "role_filter": "button",
        "app_name": "Figma",
    }
    assert app_scoped_click[0]["observation_evidence"] == {
        "source_tool": "desktop.read_ui",
        "strategy": "app_scoped_semantic_ui_tool",
    }

    safe_level_click = custom_api_agent_module._auto_discovered_followup_requests(
        selection_payload,
        ["desktop.read_ui", "desktop.safe_click", "desktop.click"],
        timeline,
    )
    assert [request["tool"] for request in safe_level_click] == [
        "desktop.safe_click",
        "desktop.read_ui",
    ]
    assert safe_level_click[0]["input"] == {"x": 120, "y": 240}
    assert safe_level_click[0]["observation_evidence"] == {
        "source_tool": "desktop.read_ui",
        "strategy": "observed_center",
        "center": {"x": 120, "y": 240},
    }

    low_level_click = custom_api_agent_module._auto_discovered_followup_requests(
        selection_payload,
        ["desktop.read_ui", "desktop.click"],
        timeline,
    )
    assert [request["tool"] for request in low_level_click] == [
        "desktop.click",
        "desktop.read_ui",
    ]
    assert low_level_click[0]["tool"] == "desktop.click"
    assert low_level_click[0]["input"] == {"x": 120, "y": 240, "click_count": 1}
    assert low_level_click[0]["observation_evidence"] == {
        "source_tool": "desktop.read_ui",
        "strategy": "observed_center",
        "center": {"x": 120, "y": 240},
    }
    event_timeline: list[dict[str, Any]] = []
    loop = _private_runtime_loop()
    loop._record_auto_model_followup_app_write_plan(
        low_level_click,
        timeline=event_timeline,
    )
    planned = next(
        event for event in event_timeline if event["event"] == "agent.desktop.intent_planned"
    )
    assert planned["action_target"] == {
        "kind": "desktop_observed_action",
        "action": "click",
        "target": "登录",
        "role_filter": "button",
    }
    assert planned["observation_evidence"] == {
        "source_tool": "desktop.read_ui",
        "strategy": "observed_center",
        "center": {"x": 120, "y": 240},
    }
    restored = loop._latest_uncompleted_daily_desktop_sequence(event_timeline)
    assert restored is not None
    assert restored["requests"][0]["action_target"] == planned["action_target"]
    assert restored["requests"][0]["observation_evidence"] == planned["observation_evidence"]
    completion_timeline = [
        _timeline(
            "agent.tool.call",
            "desktop.click",
            input_preview={"x": 120, "y": 240, "click_count": 1},
            result={"ok": True, "summary": "Clicked observed target"},
        ),
        _timeline(
            "agent.tool.call",
            "desktop.read_ui",
            input_preview={"role_filter": "button", "limit": 80},
            result={
                "ok": True,
                "data": {"elements": [{"label": "登录", "center": {"x": 120, "y": 240}}]},
            },
        )
    ]
    assert loop._direct_daily_desktop_sequence_result(
        low_level_click,
        completion_timeline,
        tool_timeline_start=0,
    )
    completed = next(
        event
        for event in completion_timeline
        if event["event"] == "agent.desktop.intent_completed"
    )
    assert completed["action_target"] == planned["action_target"]
    assert completed["observation_evidence"] == planned["observation_evidence"]
    assert [step["tool"] for step in completed["steps"]] == [
        "desktop.click",
        "desktop.read_ui",
    ]
    assert custom_api_agent_module._auto_discovered_followup_requests(
        selection_payload,
        ["desktop.read_ui", "desktop.click"],
        [
            _timeline(
                "agent.tool.call",
                "desktop.read_ui",
                result={"ok": True, "data": {"elements": [{"label": "登录"}]}},
            )
        ],
    ) == []


