def test_model_followup_context_skips_runtime_resolvable_discovered_app_operation_plan() -> None:
    prompt = "找一个 PDF 阅读器，向下滚动两页"
    allowed_tools = [
        "desktop.list_apps",
        "app.open",
        "app.focus_and_safe_scroll",
        "screen.capture",
    ]
    decision = RuntimePlanner().decision(prompt, allowed_tools=allowed_tools)
    planner_requests = planner_tool_requests(prompt, allowed_tools)
    selection_payload = planner_selection_payload(
        decision=decision,
        planner_requests=planner_requests,
        legacy_requests=[],
        selected_requests=planner_requests,
        selected_source="runtime_planner",
        selected_reason="runtime_planner_direct",
    )

    followup_context = custom_api_agent_module._model_followup_context_payload(
        planner_requests,
        selection_payload,
        allowed_tools=allowed_tools,
        timeline=[
            _timeline(
                "agent.tool.call",
                "desktop.list_apps",
                input_preview={"query": "pdf", "limit": 20},
                result={
                    "ok": True,
                    "action": "desktop.list_apps",
                    "data": {
                        "query": "pdf",
                        "apps": [
                            {
                                "name": "Preview",
                                "path": "/System/Applications/Preview.app",
                                "match_score": 90,
                            }
                        ],
                    },
                },
            )
        ],
    )
    requests = custom_api_agent_module._model_followup_pending_plan_requests(
        followup_context,
        allowed_tools,
    )

    assert "pending_plan_steps" not in followup_context
    assert requests == []
    assert [
        step.step_id
        for step in decision.plan.tool_plan.steps
        if step.tool_name
    ] == [
        "discover_apps-desktop-state",
        "open-selected-discovered-app",
        "scroll-selected-discovered-app",
        "verify-selected-discovered-app-action",
    ]
    assert [request["tool"] for request in planner_requests] == [
        "desktop.list_apps",
        "app.open",
        "app.focus_and_safe_scroll",
        "screen.capture",
    ]
    assert "continue_to_model" not in planner_requests[0]
