def test_auto_replan_terminal_data_analysis_command_writes_report(tmp_path) -> None:
    source = tmp_path / "sales.csv"
    source.write_text("month,revenue\nJan,10\nFeb,20\n", encoding="utf-8")
    command = custom_api_agent_module._terminal_data_analysis_replan_command(
        "sales.csv",
        artifact_path="analysis-report.md",
        source_kind="csv",
    )

    result = subprocess.run(
        command,
        cwd=tmp_path,
        shell=True,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        timeout=10,
        check=False,
    )

    assert result.returncode == 0
    report = (tmp_path / "analysis-report.md").read_text(encoding="utf-8")
    assert "row_count: 2" in report
    assert "column_count: 2" in report
    assert "month, revenue" in report
    assert "[artifact_written] analysis-report.md" in result.stdout


def test_runtime_planner_progress_completes_blocked_step_after_replan_recovery() -> None:
    decision = RuntimePlanner().decision(
        "请分析 legacy-report.xls 并输出报告",
        allowed_tools=[
            "workspace.read",
            "desktop.open_path",
            "browser.current_page",
            "terminal.run",
            "artifact.write",
        ],
    )
    loop = _private_runtime_loop()
    timeline = [
        _timeline(
            "agent.task.todo.updated",
            "Inspect data source",
            source="runtime_planner",
            decision_id=decision.decision_id,
            plan_id=decision.plan.plan_id,
            step_id="inspect-data-source",
            tool="workspace.read",
            status="blocked",
            todo={"status": "blocked", "title": "Inspect data source"},
        ),
        _timeline(
            "agent.task.checkpoint.updated",
            "Verify Inspect data source",
            source="runtime_planner",
            decision_id=decision.decision_id,
            plan_id=decision.plan.plan_id,
            step_id="inspect-data-source",
            tool="workspace.read",
            status="blocked",
            checkpoint={"status": "blocked", "title": "Verify Inspect data source"},
        ),
    ]
    tool_timeline_start = len(timeline)
    timeline.append(
        _timeline(
            "agent.tool.call",
            "desktop.open_path",
            input_preview={"path": "legacy-report.xls"},
            result={"ok": True, "data": {"path": "legacy-report.xls"}},
            step_id="inspect-data-source",
            capability_id="file.workspace_read",
            replan_request_id="replan-file",
            replan_trigger="tool_failure",
        )
    )

    loop._record_runtime_planner_task_progress_events(
        decision,
        timeline=timeline,
        tool_timeline_start=tool_timeline_start,
        run_id="run-file-recovery",
    )

    completed_todo = [
        event
        for event in timeline
        if event["event"] == "agent.task.todo.updated"
        and event["step_id"] == "inspect-data-source"
        and event["status"] == "completed"
    ][0]
    completed_checkpoint = [
        event
        for event in timeline
        if event["event"] == "agent.task.checkpoint.updated"
        and event["step_id"] == "inspect-data-source"
        and event["status"] == "completed"
    ][0]
    assert completed_todo["source_event"]["event"] == "agent.tool.call"
    assert completed_todo["source_event"]["detail"] == "desktop.open_path"
    assert completed_todo["source_event"]["request_id"] == ""
    assert completed_todo["source_event"]["tool_call_id"].startswith(
        "test-tool-call-"
    )
    assert completed_checkpoint["source_event"] == completed_todo["source_event"]


