def test_daily_desktop_metadata_tool_request_filters_retry_actions() -> None:
    metadata = {
        "desktop_permission_recovery": True,
        "desktop_permission_retry": True,
        "recovery_action_kind": "retry_original",
        "recovery_tool": "media.apple_music_play",
        "recovery_input": {"query": "超时空辉夜姬"},
    }

    assert daily_desktop_metadata_tool_request(metadata) == {
        "protocol": "json_fallback",
        "tool": "media.apple_music_play",
        "input": {"query": "超时空辉夜姬"},
        "source": "daily_desktop_metadata",
        "planning_reason": "structured_recovery_metadata",
    }
    assert daily_desktop_metadata_tool_request(metadata, ["media.apple_music_play"]) is not None
    assert daily_desktop_metadata_tool_request(metadata, ["app.open"]) is None
    assert daily_desktop_metadata_tool_request(
        {
            "desktop_permission_recovery": True,
            "desktop_permission_retry": True,
            "recovery_tool": "terminal.run",
            "recovery_input": {"command": "rm -rf /"},
        }
    ) is None


def test_custom_api_agent_loop_executes_desktop_intent_with_real_tool_runner_before_model() -> None:
    budget = FakeBudget()
    order: list[str] = []
    timeline: list[dict[str, Any]] = []
    artifacts: list[dict[str, Any]] = []
    run_events: list[dict[str, Any]] = []
    broker = RecordingDesktopBroker(order)
    projection = RuntimeToolLoopProjectionBuilder()
    tool_call_events = RecordingToolCallEvents(run_events)
    trace_events = NoopTraceEvents()
    executor = RuntimeToolCallExecutor(
        normalize_tool_name=normalize_tool_name,
        input_preview=tool_input_preview,
        run_budget=lambda _run_id, _timeline_value: budget,
        validate_tool_payload=RuntimeToolOperations.validate_tool_payload,
        limit_tool_result=lambda value: value,
        timeline_factory=_timeline,
        tool_call_events=tool_call_events,
        trace_events=trace_events,
        append_run_event=lambda run_id, event_type, payload: run_events.append(
            {"run_id": run_id, "event_type": event_type, "payload": payload}
        ),
        allows_tool=PolicyGate.allows_tool,
    )
    runner = RuntimeToolRequestRunner(
        normalize_tool_name=normalize_tool_name,
        input_preview=tool_input_preview,
        run_budget=lambda _run_id, _timeline_value: budget,
        user_goal_from_messages=lambda messages: str(messages[1].get("content") or ""),
        goal_disallows_tool=lambda _goal, _tool: "",
        timeline_factory=_timeline,
        append_run_event=lambda run_id, event_type, payload: run_events.append(
            {"run_id": run_id, "event_type": event_type, "payload": payload}
        ),
        tool_loop_projection=projection,
        pending_approval_builder=NoopPendingApprovalBuilder(),
        call_agent_tool=executor.execute,
    )
    operations = RuntimeToolOperations(
        tool_request_runner=runner,
        tool_call_executor=executor,
    )

    def call_model(*_args, **_kwargs):
        raise AssertionError("allowed custom desktop intent should not ask the model to restate permissions")

    loop = RuntimeCustomApiAgentLoop(
        agent_model_config_private=lambda _agent: {
            "base_url": "https://model.local",
            "model": "m",
            "api_key": "k",
        },
        compile_agent_runtime=lambda _agent: {
            "tool_policy": {
                "allowed_tools": [
                    "media.apple_music_play",
                    "media.music_app_open_and_play",
                    "desktop.list_apps",
                    "app.open_and_safe_shortcut",
                    "desktop.safe_type_text",
                    "desktop.search_submit",
                    "desktop.ui_elements",
                ]
            }
        },
        run_budget=lambda _run_id, _timeline_value: budget,
        check_context_budget=lambda _budget, _messages: None,
        tool_schemas=RuntimeToolOperations.model_tool_schemas,
        normalize_tool_iteration=lambda value: int(value or 0),
        max_tool_iterations=3,
        operating_doctrine="Use desktop tools for desktop intents.",
        memory_tool_names=set(),
        future_task_tool_names=set(),
        call_model=call_model,
        coalesce_model_message=lambda value: value,
        message_visible_content_text=lambda message: str(message.get("content") or ""),
        model_message_metadata=lambda _message: {},
        tool_requests_from_message=RuntimeToolOperations.tool_requests_from_message,
        timeline_factory=_timeline,
        limit_model_output=lambda value: (str(value), False),
        model_output_text_factory=agent_runtime._ModelOutputText,
        tool_loop_projection=projection,
        run_tool_requests=operations.run_tool_requests,
        error_type=agent_runtime.AgentRuntimeError,
        append_run_event=lambda run_id, event_type, payload: run_events.append(
            {"run_id": run_id, "event_type": event_type, "payload": payload}
        ),
    )

    result = loop.run(
        {
            "agent_id": "agent-music",
            "name": "Music Agent",
            "desktop_execution_policy": {
                "mode": "allow",
                "allow_live_foreground": True,
                "source": "test_explicit_supervised_execution",
            },
        },
        "打开 Apple Music 播放超时空辉夜姬",
        broker=broker,
        timeline=timeline,
        artifacts=artifacts,
        run_id="run-real-desktop-intent",
        budget=budget,
    )

    assert str(result) == "已在 Apple Music 播放：超时空辉夜姬 - KAF。"
    assert order == ["tool"]
    assert broker.calls == [("media.apple_music_play", {"query": "超时空辉夜姬"}, False)]
    assert budget.tool_claims == [("media.apple_music_play", False)]
    assert budget.claims == 0
    assert _planner_selection_events(timeline)[0]["selected_tools"] == ["media.apple_music_play"]
    non_planner_timeline = _non_planner_timeline_events(timeline)
    assert [event["event"] for event in non_planner_timeline] == [
        "agent.desktop.intent_planned",
        "agent.tool.started",
        "agent.tool.call",
        "agent.desktop.intent_completed",
    ]
    tool_call_event = next(
        event for event in non_planner_timeline if event["event"] == "agent.tool.call"
    )
    assert tool_call_event["detail"] == "media.apple_music_play"
    assert tool_call_event["result"]["ok"] is True
    assert non_planner_timeline[-1]["summary"] == "已在 Apple Music 播放：超时空辉夜姬 - KAF。"
    assert non_planner_timeline[0]["tool"] == "media.apple_music_play"
    assert non_planner_timeline[0]["source"] == "runtime_planner"
    non_planner_run_events = _non_planner_run_events(run_events)
    assert [event["event_type"] for event in non_planner_run_events] == [
        "agent.desktop.intent_planned",
        "agent.tool.policy_decision",
        "tool.requested",
        "tool.started",
        "tool.completed",
        "agent.tool.call",
        "agent.desktop.intent_completed",
    ]
    assert non_planner_run_events[0]["payload"]["tool"] == "media.apple_music_play"
    assert non_planner_run_events[0]["payload"]["source"] == "runtime_planner"
    assert non_planner_run_events[1]["payload"]["tool"] == "media.apple_music_play"
    assert non_planner_run_events[1]["payload"]["decision"] == "allow"
    assert non_planner_run_events[1]["payload"]["reason"] == "agent_tool_policy"
    assert non_planner_run_events[1]["payload"]["policy_overlay"] is False
    assert non_planner_run_events[-1]["payload"]["summary"] == "已在 Apple Music 播放：超时空辉夜姬 - KAF。"


def test_runtime_tool_executor_preserves_dov_replan_trace_fields() -> None:
    budget = FakeBudget()
    order: list[str] = []
    timeline: list[dict[str, Any]] = []
    run_events: list[dict[str, Any]] = []
    broker = RecordingDesktopBroker(order)
    tool_call_events = RecordingToolCallEvents(run_events)
    executor = RuntimeToolCallExecutor(
        normalize_tool_name=normalize_tool_name,
        input_preview=tool_input_preview,
        run_budget=lambda _run_id, _timeline_value: budget,
        validate_tool_payload=lambda _tool_name, _payload: None,
        limit_tool_result=lambda value: value,
        timeline_factory=_timeline,
        tool_call_events=tool_call_events,
        trace_events=NoopTraceEvents(),
        append_run_event=lambda run_id, event_type, payload: run_events.append(
            {"run_id": run_id, "event_type": event_type, "payload": payload}
        ),
        allows_tool=PolicyGate.allows_tool,
    )

    result = executor.execute(
        {
            "tool": "desktop.ui_elements",
            "input": {"role_filter": "button", "limit": 80},
            "source": "runtime_planner",
            "planning_reason": "planner_desktop_operation",
            "decision_id": "decision-dov",
            "plan_id": "runtime-plan-dov",
            "tool_plan_id": "tool-plan-dov",
            "intent_kind": "desktop_operation",
            "step_id": "verify-desktop-result",
            "capability_id": "desktop.visual_verification",
            "runtime_doctrine": "discover_operate_verify",
            "runtime_stage": "verify",
            "runtime_role": "verify_result",
            "risk_level": "medium",
            "policy_reason": "Verification touches foreground UI.",
            "requires_observation": True,
            "requires_post_action_verification": False,
            "replan_triggers": ["verification_failed"],
            "replan_signal_ids": ["replan-verify"],
            "action_target": {
                "action": "click",
                "label": "Open result",
                "app_name": "Music",
            },
            "observation_evidence": {
                "strategy": "observed_center_fallback",
                "observed_center": {"x": 180, "y": 90},
                "source_tool": "desktop.ui_elements",
            },
            "observation_retry": {
                "from_tool": "desktop.ui_elements",
                "reason": "target_not_found",
                "target": "Open result",
            },
        },
        ["desktop.ui_elements"],
        broker,
        timeline,
        run_id="run-dov-trace",
        budget=budget,
    )

    assert result["ok"] is True
    tool_call = next(event for event in timeline if event["event"] == "agent.tool.call")
    assert tool_call["runtime_stage"] == "verify"
    assert tool_call["runtime_role"] == "verify_result"
    assert tool_call["risk_level"] == "medium"
    assert tool_call["policy_reason"] == "Verification touches foreground UI."
    assert tool_call["requires_observation"] is True
    assert tool_call["requires_post_action_verification"] is False
    assert tool_call["replan_triggers"] == ["verification_failed"]
    assert tool_call["replan_signal_ids"] == ["replan-verify"]
    assert tool_call["action_target"]["label"] == "Open result"
    assert tool_call["observation_evidence"]["observed_center"] == {"x": 180, "y": 90}
    assert tool_call["observation_retry"] == {
        "from_tool": "desktop.ui_elements",
        "reason": "target_not_found",
        "target": "Open result",
    }

    completed = next(
        event for event in run_events if event["event_type"] == "tool.completed"
    )
    assert completed["payload"]["runtime_stage"] == "verify"
    assert completed["payload"]["risk_level"] == "medium"
    assert completed["payload"]["policy_reason"] == "Verification touches foreground UI."
    assert completed["payload"]["replan_triggers"] == ["verification_failed"]
    assert completed["payload"]["action_target"]["app_name"] == "Music"
    assert completed["payload"]["observation_evidence"]["strategy"] == "observed_center_fallback"
    assert completed["payload"]["observation_retry"]["reason"] == "target_not_found"
    agent_tool_call = next(
        event for event in run_events if event["event_type"] == "agent.tool.call"
    )
    assert agent_tool_call["payload"]["runtime_doctrine"] == "discover_operate_verify"
    assert agent_tool_call["payload"]["replan_signal_ids"] == ["replan-verify"]
    assert agent_tool_call["payload"]["action_target"]["action"] == "click"
    assert agent_tool_call["payload"]["observation_evidence"]["source_tool"] == "desktop.ui_elements"
    assert agent_tool_call["payload"]["observation_retry"]["from_tool"] == "desktop.ui_elements"
    snapshots = tool_call_snapshots_from_events(
        [
            PublicRunEvent(
                event_id=f"event-{index}",
                run_id=event["run_id"],
                sequence=index,
                event_type=event["event_type"],
                payload=event["payload"],
            )
            for index, event in enumerate(run_events, start=1)
        ]
    )
    completed_snapshot = next(
        snapshot for snapshot in snapshots if snapshot.status == "completed"
    )
    assert completed_snapshot.metadata["action_target"] == {
        "action": "click",
        "label": "Open result",
        "app_name": "Music",
    }
    assert completed_snapshot.metadata["observation_evidence"] == {
        "strategy": "observed_center_fallback",
        "observed_center": {"x": 180, "y": 90},
        "source_tool": "desktop.ui_elements",
    }
    assert completed_snapshot.metadata["observation_retry"] == {
        "from_tool": "desktop.ui_elements",
        "reason": "target_not_found",
        "target": "Open result",
    }


def test_runtime_tool_runner_skips_unresolved_selected_discovered_app() -> None:
    budget = FakeBudget()
    timeline: list[dict[str, Any]] = []
    messages = [
        {"role": "system", "content": "Use tools."},
        {"role": "user", "content": "打开 PixelForge"},
    ]
    run_events: list[dict[str, Any]] = []
    tool_calls: list[tuple[str, dict[str, Any]]] = []

    def call_agent_tool(
        tool_request: dict[str, Any],
        _allowed_tools: list[str],
        _broker: Any,
        timeline_value: list[dict[str, Any]],
        **_kwargs: Any,
    ) -> dict[str, Any]:
        tool = str(tool_request.get("tool") or "")
        payload = tool_request.get("input") if isinstance(tool_request.get("input"), dict) else {}
        tool_calls.append((tool, dict(payload)))
        assert tool == "desktop.list_apps"
        result = {
            "ok": True,
            "action": "desktop.list_apps",
            "summary": "No installed apps matching PixelForge",
            "data": {"query": "PixelForge", "apps": [], "count": 0},
        }
        timeline_value.append(
            _timeline(
                "agent.tool.call",
                tool,
                input_preview=dict(payload),
                result=result,
            )
        )
        return result

    runner = RuntimeToolRequestRunner(
        normalize_tool_name=normalize_tool_name,
        input_preview=tool_input_preview,
        run_budget=lambda _run_id, _timeline_value: budget,
        user_goal_from_messages=lambda value: str(value[1].get("content") or ""),
        goal_disallows_tool=lambda _goal, _tool: "",
        timeline_factory=_timeline,
        append_run_event=lambda run_id, event_type, payload: run_events.append(
            {"run_id": run_id, "event_type": event_type, "payload": payload}
        ),
        tool_loop_projection=RuntimeToolLoopProjectionBuilder(),
        pending_approval_builder=NoopPendingApprovalBuilder(),
        call_agent_tool=call_agent_tool,
    )

    runner.run(
        [
            {
                "protocol": "json_fallback",
                "tool": "desktop.list_apps",
                "input": {"query": "PixelForge", "limit": 20},
                "source": "runtime_planner",
                "planning_reason": "planner_desktop_operation",
            },
            {
                "protocol": "json_fallback",
                "tool": "app.open",
                "input": {
                    "app_name": "<selected app from desktop.list_apps>",
                    "selection_source": "desktop.list_apps",
                    "query": "PixelForge",
                },
                "source": "runtime_planner",
                "planning_reason": "planner_desktop_operation",
            },
        ],
        ["desktop.list_apps", "app.open"],
        broker={},
        messages=messages,
        timeline=timeline,
        artifacts=[],
        next_iteration=1,
        run_id="run-unresolved-app",
        budget=budget,
    )

    assert tool_calls == [("desktop.list_apps", {"query": "PixelForge", "limit": 20})]
    skipped = next(event for event in timeline if event["event"] == "agent.tool.skipped")
    assert skipped["detail"] == "app.open"
    assert skipped["result"]["error"] == "app_resolution_failed"
    assert skipped["result"]["blocked_by_app_resolution"] is True
    assert skipped["result"]["recovery_actions"] == [
        {
            "label": "重新发现应用",
            "tool": "desktop.list_apps",
            "input": {"query": "PixelForge", "limit": 20},
            "permission_target": "app_discovery",
            "risk_level": "low",
        }
    ]
    assert budget.tool_claims == [("app.open", False)]
    skipped_run_event = next(
        event for event in run_events if event["event_type"] == "agent.tool.skipped"
    )
    assert skipped_run_event["payload"]["result"]["error"] == "app_resolution_failed"
    replan_run_event = next(
        event for event in run_events if event["event_type"] == "agent.replan.requested"
    )
    assert replan_run_event["payload"]["metadata"]["recovery_actions"] == skipped["result"][
        "recovery_actions"
    ]


def test_app_resolution_keeps_canonical_alias_across_resumed_verification() -> None:
    request = {
        "tool": "desktop.ui_elements",
        "input": {
            "app_name": "WeChat",
            "selection_source": "desktop.list_apps",
            "query": "微信",
            "role_filter": "text",
        },
    }

    resolution = tool_execution_module._tool_request_app_name_resolution(request, [])
    resolved_request = tool_execution_module._tool_request_with_app_name_resolution(
        request,
        resolution,
    )

    assert resolution == {
        "tool": "desktop.ui_elements",
        "field": "app_name",
        "requested_app_name": "微信",
        "resolved_app_name": "WeChat",
        "source_tool": "desktop.list_apps",
        "app_resolution_confidence": "explicit",
        "app_resolution_reason": "explicit_app_name_without_selection_evidence",
    }
    assert resolved_request["input"] == {
        "app_name": "WeChat",
        "role_filter": "text",
    }
    assert tool_execution_module._tool_request_app_name_resolution(
        {
            "tool": "desktop.ui_elements",
            "input": {
                "app_name": "WeChat",
                "selection_source": "desktop.list_apps",
                "query": "Slack",
            },
        },
        [],
    ) == {}
    for app_name, query in (
        ("Google Chrome Helper", "Chrome"),
        ("WeChat Beta", "WeChat"),
        ("Slack Helper", "Slack"),
        ("Notes Importer", "Notes"),
    ):
        assert tool_execution_module._tool_request_app_name_resolution(
            {
                "tool": "desktop.ui_elements",
                "input": {
                    "app_name": app_name,
                    "selection_source": "desktop.list_apps",
                    "query": query,
                },
            },
            [],
        ) == {}
    for app_name, query in (("Terminal", "terminal"), ("播放器", "播放器")):
        assert tool_execution_module._tool_request_app_name_resolution(
            {
                "tool": "desktop.ui_elements",
                "input": {
                    "app_name": app_name,
                    "selection_source": "desktop.list_apps",
                    "query": query,
                },
            },
            [],
        ) == {}
    assert tool_execution_module._tool_request_app_name_resolution(
        {
            "tool": "desktop.ui_elements",
            "input": {
                "app_name": "Google Chrome",
                "selection_source": "desktop.list_apps",
                "query": "默认浏览器",
            },
        },
        [],
    ) == {}


def test_runtime_replan_blocks_unrequested_capture_and_retries_discovery_after_new_evidence() -> None:
    replan_payload = {
        "request_id": "replan-unresolved-app",
        "trigger": "tool_failure",
        "source_step_id": "open-selected-discovered-app",
        "source_tool_name": "app.open",
        "input_preview": {
            "app_name": "<selected app from desktop.list_apps>",
            "query": "PixelForge",
        },
        "metadata": {
            "recovery_actions": [
                {
                    "tool": "desktop.list_apps",
                    "input": {"query": "PixelForge", "limit": 20},
                    "risk_level": "low",
                },
                {
                    "tool": "screen.capture",
                    "input": {"reason": "ask the user to identify the app"},
                    "risk_level": "low",
                },
            ]
        },
    }
    stalled_discovery = _timeline(
        "agent.tool.call",
        "desktop.list_apps",
        input_preview={"query": "PixelForge", "limit": 20},
        result={
            "ok": True,
            "data": {"query": "PixelForge", "apps": [], "count": 0},
        },
    )

    immediate = tool_execution_module._runtime_replan_auto_recovery_action_requests(
        replan_payload,
        allowed_tools=["desktop.list_apps", "screen.capture"],
        remaining_requests=[],
        timeline=[stalled_discovery],
        tool_timeline_start=0,
    )
    after_evidence = tool_execution_module._runtime_replan_auto_recovery_action_requests(
        replan_payload,
        allowed_tools=["desktop.list_apps", "screen.capture"],
        remaining_requests=[],
        timeline=[
            stalled_discovery,
            _timeline(
                "agent.model.followup_context",
                "User confirmed the app was just installed; retry discovery.",
            ),
        ],
        tool_timeline_start=0,
    )
    after_blocked_update = tool_execution_module._runtime_replan_auto_recovery_action_requests(
        replan_payload,
        allowed_tools=["desktop.list_apps", "screen.capture"],
        remaining_requests=[],
        timeline=[
            stalled_discovery,
            _timeline(
                "agent.replan.recovery.updated",
                "Rediscovery still blocked",
                request_id="replan-unresolved-app",
                status="blocked",
                result_preview={"ok": False, "error": "app_resolution_failed"},
            ),
        ],
        tool_timeline_start=0,
    )

    assert immediate == []
    assert after_blocked_update == []
    assert [request["tool"] for request in after_evidence] == ["desktop.list_apps"]


def test_runtime_tool_runner_resolves_selected_app_for_ui_readback() -> None:
    budget = FakeBudget()
    timeline: list[dict[str, Any]] = []
    messages = [
        {"role": "system", "content": "Use tools."},
        {"role": "user", "content": "打开一个画图应用后看看界面"},
    ]
    run_events: list[dict[str, Any]] = []
    tool_calls: list[tuple[str, dict[str, Any]]] = []

    def call_agent_tool(
        tool_request: dict[str, Any],
        _allowed_tools: list[str],
        _broker: Any,
        timeline_value: list[dict[str, Any]],
        **_kwargs: Any,
    ) -> dict[str, Any]:
        tool = str(tool_request.get("tool") or "")
        payload = tool_request.get("input") if isinstance(tool_request.get("input"), dict) else {}
        tool_calls.append((tool, dict(payload)))
        if tool == "desktop.list_apps":
            result = {
                "ok": True,
                "action": "desktop.list_apps",
                "summary": "Found Figma",
                "data": {
                    "query": "image",
                    "apps": [
                        {
                            "name": "Figma",
                            "path": "/Applications/Figma.app",
                            "match_score": 94,
                        }
                    ],
                },
            }
        elif tool == "desktop.ui_elements":
            result = {
                "ok": True,
                "action": "desktop.ui_elements",
                "summary": "Read Figma UI",
                "data": {"app_name": payload.get("app_name"), "elements": []},
            }
        else:
            raise AssertionError(f"unexpected tool: {tool}")
        timeline_value.append(
            _timeline(
                "agent.tool.call",
                tool,
                input_preview=dict(payload),
                result=result,
            )
        )
        return result

    runner = RuntimeToolRequestRunner(
        normalize_tool_name=normalize_tool_name,
        input_preview=tool_input_preview,
        run_budget=lambda _run_id, _timeline_value: budget,
        user_goal_from_messages=lambda value: str(value[1].get("content") or ""),
        goal_disallows_tool=lambda _goal, _tool: "",
        timeline_factory=_timeline,
        append_run_event=lambda run_id, event_type, payload: run_events.append(
            {"run_id": run_id, "event_type": event_type, "payload": payload}
        ),
        tool_loop_projection=RuntimeToolLoopProjectionBuilder(),
        pending_approval_builder=NoopPendingApprovalBuilder(),
        call_agent_tool=call_agent_tool,
    )

    runner.run(
        [
            {
                "protocol": "json_fallback",
                "tool": "desktop.list_apps",
                "input": {"query": "image", "limit": 20},
                "source": "runtime_planner",
                "planning_reason": "planner_desktop_operation",
            },
            {
                "protocol": "json_fallback",
                "tool": "desktop.ui_elements",
                "input": {
                    "app_name": "<selected app from desktop.list_apps>",
                    "selection_source": "desktop.list_apps",
                    "query": "image",
                    "limit": 80,
                },
                "source": "runtime_planner",
                "planning_reason": "planner_desktop_operation",
            },
        ],
        ["desktop.list_apps", "desktop.ui_elements"],
        broker={},
        messages=messages,
        timeline=timeline,
        artifacts=[],
        next_iteration=1,
        run_id="run-selected-app-ui-readback",
        budget=budget,
    )

    assert tool_calls == [
        ("desktop.list_apps", {"query": "image", "limit": 20}),
        ("desktop.ui_elements", {"app_name": "Figma", "limit": 80}),
    ]
    resolved = [
        event for event in timeline if event["event"] == "agent.tool.input_resolved"
    ]
    assert resolved[0]["resolved_app_name"] == "Figma"
    assert run_events[-1]["event_type"] == "agent.tool.input_resolved"


def test_runtime_planner_replans_unresolved_selected_discovered_app_skip() -> None:
    decision = RuntimePlanner().decision(
        "找一个 PDF 阅读器，向下滚动两页",
        allowed_tools=[
            "desktop.list_apps",
            "app.open",
            "app.focus_and_safe_scroll",
            "screen.capture",
        ],
    )
    appended_events: list[dict[str, Any]] = []
    loop = _private_runtime_loop(
        append_run_event=lambda run_id, event_type, payload: appended_events.append(
            {"run_id": run_id, "event_type": event_type, "payload": payload}
        )
    )
    timeline: list[dict[str, Any]] = []
    loop._record_runtime_planner_events(
        decision,
        timeline=timeline,
        run_id="run-unresolved-app-replan",
    )
    tool_timeline_start = len(timeline)
    timeline.append(
        _timeline(
            "agent.tool.skipped",
            "app.open",
            input_preview={
                "app_name": "<selected app from desktop.list_apps>",
                "selection_source": "desktop.list_apps",
                "query": "pdf",
            },
            result={
                "ok": False,
                "skipped": True,
                "blocked_by_app_resolution": True,
                "error": "app_resolution_failed",
                "hint": "desktop.list_apps did not return a high-confidence app match.",
                "recovery_actions": [
                    {
                        "label": "重新发现应用",
                        "tool": "desktop.list_apps",
                        "input": {"query": "pdf", "limit": 20},
                        "planning_reason": "planner_desktop_loop_auto_retry",
                        "permission_target": "app_discovery",
                        "risk_level": "low",
                        "metadata": {
                            "desktop_loop": {
                                "stage": "operate",
                                "retry_tool": "desktop.list_apps",
                                "can_auto_retry": True,
                            },
                            "runtime_stage": "operate",
                            "runtime_role": "prepare_target_app",
                        },
                        "verification_targets": [
                            {
                                "step_id": "open-selected-discovered-app",
                                "todo_id": "todo-open-selected-app",
                            }
                        ],
                    }
                ],
            },
            step_id="open-selected-discovered-app",
            capability_id="desktop.app_control",
        )
    )

    replan_payloads = loop._record_runtime_planner_replan_events(
        decision,
        timeline=timeline,
        tool_timeline_start=tool_timeline_start,
        run_id="run-unresolved-app-replan",
    )

    assert len(replan_payloads) == 1
    payload = replan_payloads[0]
    assert payload["trigger"] == "tool_failure"
    assert payload["source_step_id"] == "open-selected-discovered-app"
    assert payload["source_tool_name"] == "app.open"
    assert payload["target_capability_id"] == "desktop.app_control"
    assert payload["failure_event_type"] == "agent.tool.skipped"
    assert "app_resolution_failed" in payload["failure_detail"]
    assert payload["metadata"]["recovery_actions"] == [
        {
            "label": "重新发现应用",
            "tool": "desktop.list_apps",
            "input": {"query": "pdf", "limit": 20},
            "planning_reason": "planner_desktop_loop_auto_retry",
            "permission_target": "app_discovery",
            "risk_level": "low",
            "metadata": {
                "desktop_loop": {
                    "stage": "operate",
                    "retry_tool": "desktop.list_apps",
                    "can_auto_retry": True,
                },
                "runtime_stage": "operate",
                "runtime_role": "prepare_target_app",
            },
            "verification_targets": [
                {
                    "step_id": "open-selected-discovered-app",
                    "todo_id": "todo-open-selected-app",
                }
            ],
        }
    ]
    assert timeline[-1]["event"] == "agent.replan.requested"
    assert appended_events[-1]["event_type"] == "agent.replan.requested"
    assert appended_events[-1]["payload"]["request_id"] == payload["request_id"]
    followup_context = custom_api_agent_module._model_replan_followup_context_payload(
        replan_payloads,
        allowed_tools=[
            "desktop.list_apps",
            "app.open",
            "app.focus_and_safe_scroll",
            "screen.capture",
        ],
        timeline=timeline,
    )
    followup_message = custom_api_agent_module._model_replan_followup_context_message(
        followup_context
    )
    assert followup_context["recovery_actions"] == payload["metadata"]["recovery_actions"]
    assert "Runtime recovery actions:" in followup_message
    assert "desktop.list_apps" in followup_message
    recovery_requests = custom_api_agent_module._auto_replan_recovery_requests_with_task_context(
        replan_payloads,
        [
            "desktop.list_apps",
            "app.open",
            "app.focus_and_safe_scroll",
            "screen.capture",
        ],
        timeline,
    )
    assert len(recovery_requests) == 1
    recovery_request = recovery_requests[0]
    assert recovery_request["tool"] == "desktop.list_apps"
    assert recovery_request["input"] == {"query": "pdf", "limit": 20}
    assert recovery_request["planning_reason"] == "planner_desktop_loop_auto_retry"
    assert recovery_request["replan_recovery_identity"].startswith(
        "replan-recovery-"
    )
    assert recovery_request["replan_request_id"] == payload["request_id"]
    assert recovery_request["replan_trigger"] == "tool_failure"
    assert recovery_request["step_id"] == "open-selected-discovered-app"
    assert recovery_request["planner_step_id"] == "open-selected-discovered-app"
    assert recovery_request["continue_to_model"] is True
    verification_target = recovery_request["verification_targets"][0]
    assert verification_target["step_id"] == "open-selected-discovered-app"
    assert verification_target["todo_id"].startswith("todo-")
    assert recovery_request["task_checkpoints"][0]["after_step_id"] == "open-selected-discovered-app"
    assert recovery_request["workspace_id"]
    continuation_requests = (
        custom_api_agent_module._auto_replan_discovered_app_continuation_requests(
            replan_payloads,
            [
                {
                    "protocol": "json_fallback",
                    "tool": "desktop.list_apps",
                    "input": {"query": "pdf", "limit": 20},
                    "source": "runtime_planner",
                    "planning_reason": "planner_desktop_operation",
                    "continue_to_model": True,
                },
                {
                    "protocol": "json_fallback",
                    "tool": "app.open",
                    "input": {
                        "app_name": "<selected app from desktop.list_apps>",
                        "selection_source": "desktop.list_apps",
                        "query": "pdf",
                    },
                    "source": "runtime_planner",
                    "planning_reason": "planner_desktop_operation",
                    "step_id": "open-selected-discovered-app",
                    "capability_id": "desktop.app_control",
                },
                {
                    "protocol": "json_fallback",
                    "tool": "app.focus_and_safe_scroll",
                    "input": {
                        "app_name": "<selected app from desktop.list_apps>",
                        "selection_source": "desktop.list_apps",
                        "query": "pdf",
                        "direction": "down",
                        "amount": 2,
                    },
                    "source": "runtime_planner",
                    "planning_reason": "planner_desktop_operation",
                    "step_id": "scroll-selected-discovered-app",
                    "capability_id": "desktop.ui_operation",
                },
                {
                    "protocol": "json_fallback",
                    "tool": "screen.capture",
                    "input": {},
                    "source": "runtime_planner",
                    "planning_reason": "planner_desktop_operation",
                    "step_id": "verify-selected-discovered-app-action",
                    "capability_id": "desktop.app_discovery",
                },
            ],
            [
                "desktop.list_apps",
                "app.open",
                "app.focus_and_safe_scroll",
                "screen.capture",
            ],
            [
                *timeline,
                _timeline(
                    "agent.tool.call",
                    "desktop.list_apps",
                    input_preview={"query": "pdf", "limit": 20},
                    result={
                        "ok": True,
                        "action": "desktop.list_apps",
                        "summary": "Found PDF Expert",
                        "data": {
                            "query": "pdf",
                            "apps": [
                                {
                                    "name": "PDF Expert",
                                    "path": "/Applications/PDF Expert.app",
                                    "match_score": 94,
                                }
                            ],
                        },
                    },
                ),
            ],
        )
    )
    assert [request["tool"] for request in continuation_requests] == [
        "app.open",
        "app.focus_and_safe_scroll",
        "screen.capture",
    ]
    assert {request["planning_reason"] for request in continuation_requests} == {
        "planner_replan_discovered_app_continuation"
    }
    assert {request["replan_request_id"] for request in continuation_requests} == {
        payload["request_id"]
    }
    assert {request["replan_trigger"] for request in continuation_requests} == {
        "tool_failure"
    }
    assert all("continue_to_model" not in request for request in continuation_requests)
    assert continuation_requests[0]["input"]["query"] == "pdf"
    assert continuation_requests[1]["input"]["amount"] == 2
    assert continuation_requests[0]["task_todo"]["step_id"] == (
        "open-selected-discovered-app"
    )
    assert continuation_requests[0]["workspace_id"]
    assert continuation_requests[1]["task_todo"]["step_id"] == (
        "scroll-selected-discovered-app"
    )
    assert continuation_requests[2]["task_todo"]["step_id"] == (
        "verify-selected-discovered-app-action"
    )


def test_custom_api_agent_loop_continues_after_replan_app_rediscovery_without_model() -> None:
    budget = FakeBudget()
    run_id = "run-app-rediscovery"
    contract = GoalContract(
        contract_id="goal-contract-app-rediscovery",
        run_id=run_id,
        original_goal="找一个 PDF 阅读器，向下滚动两页",
        intent_kind="desktop_operation",
        criteria=(
            GoalCriterion(
                criterion_id="criterion-open-discovered-app",
                description="Open the app selected by discovery",
                effectful=True,
                required_capabilities=("desktop.app_control",),
                expected={
                    "state": "open",
                    "target": {
                        "kind": "desktop_app",
                        "action": "open_app",
                        "query": "pdf",
                    },
                },
                source_step_ids=("open-selected-discovered-app",),
            ),
            GoalCriterion(
                criterion_id="criterion-scroll-discovered-app",
                description="Scroll the selected app",
                effectful=True,
                required_capabilities=("desktop.ui_operation",),
                expected={
                    "state": "fulfilled",
                    "target": {
                        "kind": "desktop_ui",
                        "action": "scroll",
                        "query": "pdf",
                    },
                },
                source_step_ids=("scroll-selected-discovered-app",),
                verifier_step_ids=("verify-selected-discovered-app-action",),
            ),
        ),
    )
    timeline: list[dict[str, Any]] = [
        _timeline(
            "agent.goal.contract",
            contract.contract_id,
            run_id=run_id,
            contract_id=contract.contract_id,
            goal_contract=contract.to_payload(),
        )
    ]
    tool_runs: list[list[str]] = []
    list_apps_calls = 0
    allowed_tools = [
        "desktop.list_apps",
        "app.open",
        "app.focus_and_safe_scroll",
        "screen.capture",
    ]

    def run_tool_requests(
        tool_requests,
        _allowed_tools,
        _broker,
        _messages_arg,
        timeline_arg,
        _artifacts,
        **_kwargs,
    ):
        nonlocal list_apps_calls
        tool_runs.append([str(request.get("tool") or "") for request in tool_requests])
        for index, request in enumerate(tool_requests):
            tool = str(request.get("tool") or "")
            payload = request.get("input") if isinstance(request.get("input"), dict) else {}
            if tool == "desktop.list_apps":
                list_apps_calls += 1
                result = (
                    {
                        "ok": True,
                        "action": tool,
                        "summary": "No PDF apps",
                        "data": {"query": "pdf", "apps": [], "count": 0},
                    }
                    if list_apps_calls == 1
                    else {
                        "ok": True,
                        "action": tool,
                        "summary": "Found PDF Expert",
                        "data": {
                            "query": "pdf",
                            "apps": [
                                {
                                    "name": "PDF Expert",
                                    "path": "/Applications/PDF Expert.app",
                                    "match_score": 94,
                                }
                            ],
                        },
                    }
                )
                _append_fake_runtime_tool_call(
                    timeline_arg,
                    request,
                    result,
                    run_id=str(_kwargs.get("run_id") or ""),
                )
                continue
            if request.get("approval_required") or tool == "app.focus_and_safe_scroll":
                _raise_fake_runner_approval(
                    tool_requests,
                    index,
                    _messages_arg,
                    next_iteration=int(_kwargs.get("next_iteration") or 1),
                )
            if tool == "app.open" and list_apps_calls == 1:
                result = {
                    "ok": False,
                    "skipped": True,
                    "blocked_by_app_resolution": True,
                    "error": "app_resolution_failed",
                    "hint": "desktop.list_apps did not return a high-confidence app match.",
                    "recovery_actions": [
                        {
                            "label": "重新发现应用",
                            "tool": "desktop.list_apps",
                            "input": {"query": "pdf", "limit": 20},
                            "permission_target": "app_discovery",
                            "risk_level": "low",
                        }
                    ],
                }
                _append_fake_runtime_tool_call(
                    timeline_arg,
                    request,
                    result,
                    run_id=str(_kwargs.get("run_id") or ""),
                )
                timeline_arg[-1]["event"] = "agent.tool.skipped"
                return
            if tool == "app.open":
                result = {
                    "ok": True,
                    "action": tool,
                    "summary": "Opened PDF Expert",
                    "data": {
                        "app_name": "PDF Expert",
                        "launch_verified": True,
                    },
                }
            elif tool == "app.focus_and_safe_scroll":
                result = {
                    "ok": True,
                    "action": tool,
                    "summary": "Scrolled PDF Expert",
                    "data": {"app_name": "PDF Expert", "direction": payload.get("direction")},
                }
            elif tool == "screen.capture":
                result = {
                    "ok": True,
                    "action": tool,
                    "summary": "Captured screen",
                    "data": {"path": "artifacts/pdf-scroll.png"},
                }
            else:
                raise AssertionError(f"unexpected tool: {tool}")
            _append_fake_runtime_tool_call(
                timeline_arg,
                request,
                result,
                run_id=str(_kwargs.get("run_id") or ""),
            )

    loop = RuntimeCustomApiAgentLoop(
        agent_model_config_private=lambda _agent: {
            "base_url": "https://model.local",
            "model": "m",
            "api_key": "k",
        },
        compile_agent_runtime=lambda _agent: {
            "tool_policy": {"allowed_tools": allowed_tools},
        },
        run_budget=lambda _run_id, _timeline_value: budget,
        check_context_budget=lambda _budget, _messages: None,
        tool_schemas=lambda allowed: [{"name": tool} for tool in allowed],
        normalize_tool_iteration=lambda value: int(value or 0),
        max_tool_iterations=2,
        operating_doctrine="Use runtime planner direct desktop execution.",
        memory_tool_names=set(),
        future_task_tool_names=set(),
        call_model=lambda *_args, **_kwargs: (_ for _ in ()).throw(
            AssertionError("app rediscovery continuation should not call model")
        ),
        coalesce_model_message=lambda value: value,
        message_visible_content_text=lambda message: str(message.get("content") or ""),
        model_message_metadata=lambda _message: {},
        tool_requests_from_message=lambda _message, _content: [],
        timeline_factory=_timeline,
        limit_model_output=lambda value: (str(value), False),
        model_output_text_factory=agent_runtime._ModelOutputText,
        tool_loop_projection=FakeToolLoopProjection(),
        run_tool_requests=run_tool_requests,
        error_type=agent_runtime.AgentRuntimeError,
    )

    with pytest.raises(AgentApprovalRequired) as approval:
        loop.run(
            {"name": "Yachiyo"},
            "找一个 PDF 阅读器，向下滚动两页",
            broker={},
            timeline=timeline,
            artifacts=[],
            run_id=run_id,
        )

    pending = approval.value.pending_approval
    assert pending["tool"] == "app.focus_and_safe_scroll"
    assert "completed_tool_requests" not in pending
    assert [request["tool"] for request in pending["remaining_tool_requests"]] == [
        "screen.capture"
    ]
    assert tool_runs == [
        [
            "desktop.list_apps",
            "app.open",
            "app.focus_and_safe_scroll",
            "screen.capture",
        ],
        ["desktop.list_apps"],
        ["app.open", "app.focus_and_safe_scroll", "screen.capture"],
    ]
    assert not any(
        event["event"] == "agent.desktop.intent_completed" for event in timeline
    )
    assert timeline[-1]["event"] == "agent.desktop.intent_approval_required"


