def test_direct_desktop_permission_recovery_does_not_auto_start_approval_action() -> None:
    timeline: list[dict[str, Any]] = []
    run_events: list[dict[str, Any]] = []
    tool_order: list[str] = []

    def run_tool_requests(
        tool_requests,
        _allowed_tools,
        _broker,
        _messages,
        timeline_arg,
        _artifacts,
        **_kwargs,
    ) -> None:
        tool_name = str(tool_requests[0].get("tool") or "")
        tool_order.append(tool_name)
        if tool_name == "screen.capture":
            _append_fake_runtime_tool_call(
                timeline_arg,
                tool_requests[0],
                {
                    "ok": False,
                    "permission_error": True,
                    "permission_targets": ["screen_recording"],
                    "recovery_actions": [
                        {
                            "label": "打开屏幕录制权限",
                            "tool": "system.settings_open",
                            "input": {"target": "屏幕录制权限"},
                            "permission_target": "screen_recording",
                            "risk_level": "low",
                        }
                    ],
                },
                run_id="run-screen-recovery-approval",
            )
            return
        if tool_name == "system.settings_open":
            raise AgentApprovalRequired(
                {
                    "tool": "system.settings_open",
                    "approval_id": "approval-settings",
                    "risk_level": "medium",
                    "policy_reason": "open_system_settings",
                    "input_preview": {"target": "屏幕录制权限"},
                }
            )

    loop = RuntimeCustomApiAgentLoop(
        agent_model_config_private=lambda _agent: {},
        compile_agent_runtime=lambda _agent: {
            "tool_policy": {"allowed_tools": ["screen.capture", "system.settings_open"]}
        },
        run_budget=lambda _run_id, _timeline_value: FakeBudget(),
        check_context_budget=lambda _budget, _messages: None,
        tool_schemas=lambda _allowed_tools: [],
        normalize_tool_iteration=lambda value: int(value or 0),
        max_tool_iterations=1,
        operating_doctrine="Use desktop tools.",
        memory_tool_names=set(),
        future_task_tool_names=set(),
        call_model=lambda *_args, **_kwargs: {},
        coalesce_model_message=lambda value: value,
        message_visible_content_text=lambda message: str(message.get("content") or ""),
        model_message_metadata=lambda _message: {},
        tool_requests_from_message=lambda _message, _content: [],
        timeline_factory=_timeline,
        limit_model_output=lambda value: (str(value), False),
        model_output_text_factory=agent_runtime._ModelOutputText,
        tool_loop_projection=FakeToolLoopProjection(),
        run_tool_requests=run_tool_requests,
        error_type=agent_runtime.AgentRuntimeError,
        append_run_event=lambda run_id, event_type, payload: run_events.append(
            {"run_id": run_id, "event_type": event_type, "payload": payload}
        ),
    )

    with pytest.raises(AgentDirectOutcomeUnverified) as exc_info:
        loop.run(
            {"agent_id": MAIN_CHAT_AGENT_ID, "name": "Yachiyo"},
            "截图当前屏幕",
            broker={"broker": True},
            timeline=timeline,
            artifacts=[],
            direct_tool_request={
                "tool": "screen.capture",
                "input": {"reason": "user request"},
            },
            run_id="run-screen-recovery-approval",
        )
    result = str(exc_info.value)

    assert "缺少权限：screen_recording" in str(result)
    assert tool_order == ["screen.capture"]
    recovery_event = next(
        event
        for event in timeline
        if event.get("event") == "agent.desktop.permission_recovery"
    )
    assert recovery_event["recovery_actions"][0]["tool"] == "system.settings_open"
    assert not any(
        event.get("event") == "agent.desktop.intent_approval_required"
        for event in timeline
    )
    assert not any(
        event["event_type"] == "agent.desktop.intent_approval_required"
        for event in run_events
    )


def test_direct_desktop_permission_recovery_fails_closed_before_app_open_retry() -> None:
    tool_order: list[str] = []
    timeline: list[dict[str, Any]] = []
    play_attempts = 0

    def run_tool_requests(
        tool_requests,
        _allowed_tools,
        _broker,
        messages_arg,
        timeline_arg,
        _artifacts,
        **_kwargs,
    ) -> None:
        nonlocal play_attempts
        for request in tool_requests:
            tool_name = str(request.get("tool") or "")
            tool_order.append(tool_name)
            payload = request.get("input") if isinstance(request.get("input"), dict) else {}
            if tool_name == "media.apple_music_play":
                play_attempts += 1
                result = (
                    {
                        "ok": False,
                        "error": "Music is not ready",
                        "permission_error": True,
                        "permission_targets": ["music_app"],
                        "recovery_actions": [
                            {
                                "label": "打开 Apple Music",
                                "tool": "app.open",
                                "input": {"app_name": "Music"},
                                "permission_target": "music_app",
                                "risk_level": "low",
                            }
                        ],
                    }
                    if play_attempts == 1
                    else {
                        "ok": True,
                        "data": {
                            "track": "超时空辉夜姬",
                            "artist": "Yachiyo",
                        },
                    }
                )
            elif tool_name == "app.open":
                result = {"ok": True, "data": {"app_name": payload.get("app_name")}}
            else:
                raise AssertionError(f"unexpected tool: {tool_name}")
            _append_fake_runtime_tool_call(
                timeline_arg,
                request,
                result,
                run_id="run-music-recovery-retry",
            )
            messages_arg.append({"role": "user", "content": f"Tool result for {tool_name}: {result}"})

    loop = RuntimeCustomApiAgentLoop(
        agent_model_config_private=lambda _agent: {},
        compile_agent_runtime=lambda _agent: {
            "tool_policy": {"allowed_tools": ["media.apple_music_play", "app.open"]}
        },
        run_budget=lambda _run_id, _timeline_value: FakeBudget(),
        check_context_budget=lambda _budget, _messages: None,
        tool_schemas=lambda _allowed_tools: [],
        normalize_tool_iteration=lambda value: int(value or 0),
        max_tool_iterations=1,
        operating_doctrine="Use desktop tools.",
        memory_tool_names=set(),
        future_task_tool_names=set(),
        call_model=lambda *_args, **_kwargs: (_ for _ in ()).throw(
            AssertionError("successful recovery retry should not call the model")
        ),
        coalesce_model_message=lambda value: value,
        message_visible_content_text=lambda message: str(message.get("content") or ""),
        model_message_metadata=lambda _message: {},
        tool_requests_from_message=lambda _message, _content: [],
        timeline_factory=_timeline,
        limit_model_output=lambda value: (str(value), False),
        model_output_text_factory=agent_runtime._ModelOutputText,
        tool_loop_projection=FakeToolLoopProjection(),
        run_tool_requests=run_tool_requests,
        error_type=agent_runtime.AgentRuntimeError,
    )

    with pytest.raises(AgentDirectOutcomeUnverified) as exc_info:
        loop.run(
            {"agent_id": MAIN_CHAT_AGENT_ID, "name": "Yachiyo"},
            "播放超时空辉夜姬",
            broker={"broker": True},
            timeline=timeline,
            artifacts=[],
            direct_tool_request={
                "tool": "media.apple_music_play",
                "input": {"query": "超时空辉夜姬"},
            },
            run_id="run-music-recovery-retry",
        )

    assert exc_info.value.reason == "permission_required"
    assert exc_info.value.tool_name == "media.apple_music_play"
    assert "Music is not ready" in str(exc_info.value)
    assert tool_order == ["media.apple_music_play"]
    assert play_attempts == 1
    assert not any(
        event.get("event") == "agent.desktop.intent_planned"
        and event.get("tool") == "app.open"
        for event in timeline
    )


def test_main_chat_desktop_intent_summarizes_apple_music_control() -> None:
    open_and_play = RuntimeCustomApiAgentLoop._daily_desktop_summary(
        "media.apple_music_open_and_play",
        {},
        {
            "ok": True,
            "summary": "Opened Music and started playback",
            "data": {
                "control": "play",
                "player_state": "playing",
                "track": "超时空辉夜姬",
                "artist": "Yachiyo",
            },
        },
    )
    open_and_play_fallback = RuntimeCustomApiAgentLoop._daily_desktop_summary(
        "media.apple_music_open_and_play",
        {},
        {
            "ok": True,
            "summary": "Opened Music and attempted playback with media key fallback",
            "data": {
                "control": "play",
                "player_state": "unknown",
                "fallback": "system_media_key",
                "fallback_control": "toggle",
                "media_key": "Play/Pause",
                "playback_state_unverified": True,
            },
        },
    )
    pause = RuntimeCustomApiAgentLoop._daily_desktop_summary(
        "media.apple_music_control",
        {"action": "pause"},
        {
            "ok": True,
            "summary": "Apple Music pause executed",
            "data": {"control": "pause", "player_state": "paused"},
        },
    )
    next_track = RuntimeCustomApiAgentLoop._daily_desktop_summary(
        "media.apple_music_control",
        {"action": "next"},
        {
            "ok": True,
            "summary": "Apple Music next executed",
            "data": {
                "control": "next",
                "player_state": "playing",
                "track": "超时空辉夜姬",
                "artist": "Yachiyo",
            },
        },
    )
    next_track_fallback = RuntimeCustomApiAgentLoop._daily_desktop_summary(
        "media.apple_music_control",
        {"action": "next"},
        {
            "ok": True,
            "summary": "Apple Music next attempted via media key fallback",
            "data": {
                "control": "next",
                "player_state": "unknown",
                "fallback": "system_media_key",
                "fallback_control": "next",
                "media_key": "Next",
                "playback_state_unverified": True,
            },
        },
    )

    assert pause == "已暂停 Apple Music。"
    assert next_track == "已切到下一首 Apple Music。当前：超时空辉夜姬 - Yachiyo。"
    assert next_track_fallback == "已用媒体键尝试切到下一首 Apple Music。"
    assert open_and_play == "已打开 Apple Music 并开始播放。当前：超时空辉夜姬 - Yachiyo。"
    assert open_and_play_fallback == "已打开 Apple Music，并用媒体键尝试开始播放。"


